@Service
@Slf4j
public class CompatiblyContractService {
	@Resource
	CommonContractService commonContractService;
	@Resource
	NormalContractInfo beijingContractService;


	/**
	 * 获取正签的开工日期
	 * @param businessId
	 * @param projectOrderId
	 * @return
	 */
	public String getPlanOpenDate(Byte businessId, String projectOrderId) {
		String planStartTime = commonContractService.getPlanOpenDate(businessId, projectOrderId);
		if (StringUtils.isBlank(planStartTime)) {
			try {
				ResultDTO<ZQPlanWorkDateInfo> resultDTO = beijingContractService.queryZQPlanWorkDate(projectOrderId);
				if (resultDTO.isSuccess() && Objects.nonNull(resultDTO.getData().getPlanWorkDate())) {
					planStartTime = DateUtils.getDateStr(resultDTO.getData().getPlanWorkDate());
				}
			} catch (Exception e) {
				LOGGER.info("获取北京开工日期报错:{}, {}", projectOrderId, e.getMessage());
			}
		}

		return planStartTime;
	}
}

