	/**
	 * 根据合同code获取旧表数据
	 *
	 * @param contractCode 合同编码
	 * @return 合同字段列表
	 */
	private List<ContractField> getOldTableData(String contractCode) {
		Example example = new Example(ContractField.class);
		example.createCriteria()
			.andEqualTo("contractCode", contractCode)
			.andEqualTo("delStatus", CommonEnum.NO);
		return mapper.selectByExample(example);
	}

	/**
	 * 根据合同code获取新表数据
	 *
	 * @param contractCode 合同编码
	 * @return 合同字段分表列表
	 */
	private List<ContractFieldSharding> getNewTableData(String contractCode) {
		Example example = new Example(ContractFieldSharding.class);
		example.createCriteria()
			.andEqualTo("contractCode", contractCode)
			.andEqualTo("delStatus", CommonEnum.NO);
		return shardingMapper.selectByExample(example);
	}

	/**
	 * 批量保存合同字段数据到新表
	 *
	 * @param contractFieldList 合同字段列表
	 */
