	private static final String CONTRACT_SCRIPT_KEY_PREFIX = "nrs:contract:script:";

	/**
	 * 生成脚本任务
	 */
	public Boolean generateContractScript(String contractCode) {
		// 获取redis key
		String redisKey = CONTRACT_SCRIPT_KEY_PREFIX + contractCode;
		// 判断是否存在在途任务
		Boolean hasKey = stringRedisTemplate.hasKey(redisKey);
		if (Boolean.TRUE.equals(hasKey)) {
			LOGGER.info("合同讲解脚本生成任务已在进行中，contractCode: {}", contractCode);
		}
		// 异步请求生成脚本任务
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				//生成合同讲解脚本
				stringRedisTemplate.opsForValue().set(redisKey, "1", 90, TimeUnit.SECONDS);
				contractScriptService.asyncGenerateContractScript(contractCode);
			} catch (Exception e) {
				LOGGER.error("合同讲解脚本生成失败", e);
				// 删除在途任务标记
				stringRedisTemplate.delete(redisKey);
			} finally {
				// 删除在途任务标记
				stringRedisTemplate.delete(redisKey);
			}
		}));
		return true;
	}

