	@Resource
	ComboInfoService comboInfoService;
	@Resource
	ContractUnifyService contractUnifyService;
	public ContractComboFileDTO queryComboFileInfo(String comboCode, String projectOrderId) {
		ContractComboFileDTO contractComboFileDTO = new ContractComboFileDTO();
		// 上层有两个调用方，其中一个提供给报价使用，增加了 projectOrderId 参数，另外一个接口通过 kemonitor 观察到没有请求流量，因此直接传入 projectOrderId = null，这个日志由于观察该接口是否会有流量进入
		if (StringUtils.isBlank(projectOrderId)) {
			LOGGER.error("查询套餐时，projectOrderId 为空，需评估上层调用方");
		}
		boolean developerChannel = contractUnifyService.isDeveloperChannel(projectOrderId);
		Byte contractFormType = ContractFormTypeEnum.getCodeByDeveloperChannel(developerChannel);
		ContractComboInfo contractComboInfo = comboInfoService.getLatestContractComboInfo(comboCode, contractFormType);
		contractComboFileDTO.setDecorateRuleUrls(comboInfoService.getDecorateRule(contractComboInfo).getImgUrls());
		contractComboFileDTO.setBudgetDescUrls(comboInfoService.getBudgetDesc(contractComboInfo).getImgUrls());
		contractComboFileDTO.setMaterialUrls(comboInfoService.getMaterialList(contractComboInfo).getImgUrls());
		return contractComboFileDTO;

	}
}

