@Service
@Slf4j
public class ContractCompanyBusinessService {

	@Resource
	private ContractService contractService;

	@Resource
	private ContractCompanyService contractCompanyService;

	/**
	 * 获取项目单号、合同类型最新已签约合同主体信息
	 *
	 * @param homeOrderNo  主单号
	 * @param contractType 合同类型
	 */
	public List<ContractCompanyDTO> getLatestSignedContractCompany(String homeOrderNo, Byte contractType) {
		Contract latestContract = contractService.getLatestContract(homeOrderNo, contractType);
		if (latestContract == null) {
			return Collections.emptyList();
		}

		List<ContractCompany> companyListByCode = contractCompanyService.getCompanyListByCode(latestContract.getContractCode());
		if (CollectionUtils.isEmpty(companyListByCode)) {
			return Collections.singletonList(ContractCompanyDTO.builder()
				.contractCode(latestContract.getContractCode())
				.companyCode(latestContract.getCompanyCode())
				.decorateBusinessType(ProjectDecorateBusinessTypeEnum.HOME_DECORATE.getCode())
				.build());
		}


		List<ContractCompanyDTO> contractCompanyDTOList = new ArrayList<>();

		for (ContractCompany contractCompany : companyListByCode) {
			ContractCompanyDTO contractCompanyDTO = new ContractCompanyDTO();
			BeanUtils.copyProperties(contractCompany, contractCompanyDTO);
			contractCompanyDTOList.add(contractCompanyDTO);
		}

		return contractCompanyDTOList;
	}


	public String getDecorateEscrowContractCompany(String homeOrderNo) {
		List<ContractCompanyDTO> companyDTOS = getLatestSignedContractCompany(homeOrderNo, ContractTypeEnum.FUND_ESCROW.getCode());
		return companyDTOS.stream().filter(companyDTO -> ProjectDecorateBusinessTypeEnum.DECORATE_CODE_LIST.contains(companyDTO.getDecorateBusinessType()))
			.map(ContractCompanyDTO::getCompanyCode)
			.findFirst()
			.orElse("");
	}

}

