	public List<String> batchAddFooter(List<String> inputPdfs, String footerText, float positionXRatio, float positionYRatio) {
		LOGGER.info("批量pdf文件增加盖章关键字开始");
		long start = System.currentTimeMillis();
		List<CompletableFuture<Void>> futures = new ArrayList<>();
		List<String> modifiedPdfs = new ArrayList<>();
		Map<String, String> modifiedPdfsMap = new HashMap<>();
		UUID uuid = UUID.randomUUID();
		for (int i = 0; i < inputPdfs.size(); i++) {
			String modifiedPdf = "modified_" + uuid + "_" + (i + 1) + ".pdf";
			int finalI = i;
			CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(() -> {
				try {
					addFooter(inputPdfs.get(finalI), modifiedPdf, footerText, positionXRatio, positionYRatio);
					modifiedPdfsMap.put(inputPdfs.get(finalI), modifiedPdf);
				} catch (Exception e) {
					LOGGER.error("添加文字失败，url:{}，原因: {}", inputPdfs.get(finalI), e.getMessage(), e);
					throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "pdf添加盖章关键字失败", Level.WARN);
				}
			}, pdfExecutor);
			futures.add(pdfFuture);
		}
		CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
		inputPdfs.forEach(pdf -> modifiedPdfs.add(modifiedPdfsMap.get(pdf)));
