	/**
	 * @desc 发送短信验证码
	 * @param smsServiceSendReq
	 * @return
	 */
	public Boolean sendSmsCode(SmsServiceSendReq smsServiceSendReq) {

		Contract contractInfo = contractService.getByContractCode(smsServiceSendReq.getContractCode());
		if (Objects.isNull(contractInfo)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"该合同编号不存在");
		}

		//待业主确认状态才可发送
		if (!contractInfo.getStatus().equals(ContractStatusEnum.PENDING_USER_CONFIRM.getCode())) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"只有待业主确认状态可发送短信");
		}

		ContractUser contractUser = contractUserService.getSignerByContractCode(contractInfo.getContractCode());
		if (Objects.isNull(contractUser) || contractUser.getPhone().isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前合同不存在签约人联系方式-[phone]");
		}
		// 加解密
		String contractUserPhone = cipherService.decrypt(contractUser.getPhone());
		Boolean isLoginSignSelf = contractBusinessService.isLoginSignSelf(smsServiceSendReq.getUserId(), contractUserPhone);
		if (!isLoginSignSelf) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前登入人和签约人不一致，不允许发送短信");
		}
