public class AuditContractBpmHandler extends BpmHandler {

    @Resource
    private ContractBusinessService contractBusinessService;

    @Override
    public void handler(ProcessEventModel processEventModel, BpmStatusEnum bpmStatusEnum) {
		boolean auditResult = BpmStatusEnum.getBooleanResult(bpmStatusEnum);
		boolean terminateResult = BpmStatusEnum.getTerminateBooleanResult(bpmStatusEnum);
		LOGGER.info("[design_fee_audit_bpm] 收到回调, processInstId:{}, bpmStatusEnum:{}, auditResult:{}, terminateResult:{}",
			processEventModel.getProcessInstId(), bpmStatusEnum, auditResult, terminateResult);
		if (auditResult || terminateResult) {
			contractBusinessService.dealContractResultForBpm(processEventModel, bpmStatusEnum, ContractAuditSceneEnum.DESIGN_FEE);
        }
    }
}

