	private ContractService contractService;
	@Resource
	private ContractRedisRepoService contractRedisService;
	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Assignment(key = "asyncSignTimeCheckSchedule", cn = "异步盖章时间检查")
	public AssignmentResult asyncSignTimeCheck(AssignmentContext context) {
		List<Contract> contractList = contractService.getListByStatus(ContractStatusEnum.PENDING_COMPANY_SIGN.getCode());
		if (contractList.isEmpty()) {
			return new AssignmentResult(ResultMode.EXECUTE_SUCCESS);
		}
		for (Contract contract : contractList) {
			CompanySealAsyncResultDTO companySealAsyncResultDTO = contractRedisService.getCompanySealResult(contract.getContractCode());
            if (companySealAsyncResultDTO == null) {
				continue;
			}
			// 超过X分钟未盖章则报警
			long asyncSignTimeCheckValue = 60 * 1000 * contractApolloConfig.getAsyncSignTimeCheckValue();
			if (System.currentTimeMillis() - companySealAsyncResultDTO.getApplySealTime() > asyncSignTimeCheckValue) {
				LOGGER.error("异步盖章时间检查,时间过长还未收到盖章回调,合同信息:{}", JSON.toJSONString(contract));
			}
		}
		return new AssignmentResult(ResultMode.EXECUTE_SUCCESS);
	}

}

