@Service
@Slf4j
public class DrawingCompressionConfig {

	/*配置示例

	{
		"compressionRules": [
		{
			"pageRange": [1, 10],   //区间为左闭右开
			"sizeRangeMB": [0, 1],  //区间为左闭右开
			"dpi": 300
		},
		{
			"pageRange": [1, 10],
			"sizeRangeMB": [1, 5],
			"dpi": 150
		},
		{
			"pageRange": [11, 50],
			"sizeRangeMB": [0, 10],
			"dpi": 150
		},
		{
			"pageRange": [51, 100],
			"sizeRangeMB": [0, 50],
			"dpi": 100
		}
            ],
		"defaultDpi": 72
	}
	 */

	@Resource
	private ContractApolloConfig contractApolloConfig;

	// 配置规则类
	@Setter
	@Getter
	public static class Rule {
		private int[] pageRange;
		private double[] sizeRangeMB;
		private int dpi;
	}

	// 配置类
	@Setter
	@Getter
	public static class Config {
		private List<Rule> compressionRules;
		private int defaultDpi = 100;
	}

	// 加载配置（从 JSON 字符串）
	public  Config loadConfigFromString(String jsonConfig) throws Exception {
		ObjectMapper mapper = new ObjectMapper();
		return mapper.readValue(jsonConfig, Config.class);
	}

	// 根据规则匹配 DPI
	public  int getDpi(int pages, double fileSizeMB) throws Exception {
		Config config = loadConfigFromString(contractApolloConfig.getDrawingCompressionConfig());

		for (Rule rule : config.getCompressionRules()) {
			int[] pageRange = rule.getPageRange();
			double[] sizeRange = rule.getSizeRangeMB();

			if (pages >= pageRange[0] && pages < pageRange[1] &&
				fileSizeMB >= sizeRange[0] && fileSizeMB < sizeRange[1]) {
				LOGGER.info("根据规则匹配到DPI,dpi：{},pages：{},fileSizeMB：{}", rule.getDpi(),pages,fileSizeMB);
				return rule.getDpi();
			}
		}
		LOGGER.info("根据规则未匹配到DPI,使用默认dpi：{},pages：{},fileSizeMB：{}", config.getDefaultDpi(),pages,fileSizeMB);
