@Service
@Slf4j
public class ContractRedisRepoService {

	@Resource
	private RedisTemplate<String, String> redisTemplate;

	private static final String CONTRACT_COMPANY_SEAL_RESULT_KEY = "CONTRACT_COMPANY_SEAL_RESULT_KEY:";
	private static final String CONTRACT_FACE_AUTH_BIZ_FLOW_NO_KEY = "CONTRACT_FACE_AUTH_BIZ_FLOW_NO_KEY:";


	public CompanySealAsyncResultDTO getCompanySealResult(String contractCode) {
		String value = redisTemplate.opsForValue().get(CONTRACT_COMPANY_SEAL_RESULT_KEY + contractCode);
		if (StringUtils.isEmpty(value)) {
			return null;
		}
		LOGGER.info("从redis中获取到合同章结果:{}", value);
		return JSON.parseObject(value, CompanySealAsyncResultDTO.class);
	}

	public void removeCompanySealResult(String contractCode) {
		Boolean success = redisTemplate.delete(CONTRACT_COMPANY_SEAL_RESULT_KEY + contractCode);
		if (!Boolean.TRUE.equals(success)) {
			throw new NrsBusinessException("redis key删除失败");
		}
	}

	public void saveCompanySealResult(String contractCode, CompanySealAsyncResultDTO companySealAsyncResultDTO) {
		redisTemplate.opsForValue().set(CONTRACT_COMPANY_SEAL_RESULT_KEY + contractCode, JSON.toJSONString(companySealAsyncResultDTO), 7L, TimeUnit.DAYS);
	}

	public void saveFaceAuthBizFlowNo(String contractCode, String faceAuthBizFlowNo) {
		redisTemplate.opsForValue().set(CONTRACT_FACE_AUTH_BIZ_FLOW_NO_KEY + contractCode, faceAuthBizFlowNo, 1L, TimeUnit.DAYS);
	}

	public String getFaceAuthBizFlowNo(String contractCode) {
		String value = redisTemplate.opsForValue().get(CONTRACT_FACE_AUTH_BIZ_FLOW_NO_KEY + contractCode);
		if (StringUtils.isEmpty(value)) {
			return null;
		}

		LOGGER.info("从redis中获取到人脸识别业务流水号结果:{}", value);
		return value;
	}

	public void removeFaceAuthBizFlowNo(String contractCode) {
		Boolean success = redisTemplate.delete(CONTRACT_FACE_AUTH_BIZ_FLOW_NO_KEY + contractCode);
		if (!Boolean.TRUE.equals(success)) {
			throw new NrsBusinessException("redis key删除失败");
		}
	}
}

