public class ContractBindLogService {

    private static final int MAX_CONTENT_LENGTH = 2900;

    private static final String SYSTEM_OPERATOR_ID = "1000000000000000";
    private static final String SYSTEM_OPERATOR_NAME = "系统";

    @Resource
    private ContractLogService contractLogService;

    /**
     * 截断 content 避免超长
     */
    private String truncateContent(String content) {
        if (content != null && content.length() > MAX_CONTENT_LENGTH) {
            return content.substring(0, MAX_CONTENT_LENGTH);
        }
        return content;
    }

    /**
     * 记录换绑日志
     *
     * @param contractCode      合同编号
     * @param scene             场景描述
     * @param originalBillCode  原始单据编号
     * @param newBillCodes      换绑后的单据编号列表
     */
    public void recordBindChangeLog(String contractCode, String scene, String originalBillCode, List<String> newBillCodes) {
        try {
            Map<String, Object> contentMap = new HashMap<>(4);
            contentMap.put("scene", scene);
            contentMap.put("originalBillCode", originalBillCode);
            contentMap.put("newBillCode", newBillCodes);
            String content = truncateContent(JSON.toJSONString(contentMap));
            contractLogService.createLog(
                contractCode,
                LogTypeEnum.CONTRACT_BIND_CHANGE.getCode(),
                content,
                LogTypeEnum.CONTRACT_BIND_CHANGE.getName(),
                SYSTEM_OPERATOR_ID,
                SYSTEM_OPERATOR_NAME
            );
        } catch (Exception e) {
            LOGGER.error("记录换绑日志失败, contractCode:{}, scene:{}", contractCode, scene, e);
        }
    }

