	public static <T> List<T> parseFieldToList(ContractField field, Class<T> clazz) {
		if (field == null || StringUtils.isBlank(field.getFieldValue())) {
			return Collections.emptyList();
		}

		try {
			Type listType = TypeToken.getParameterized(List.class, clazz).getType();
			return new Gson().fromJson(field.getFieldValue(), listType);
		} catch (Exception e) {
			LOGGER.error("解析字段失败, fieldKey: {}, fieldValue: {}",
				field.getFieldKey(), field.getFieldValue(), e);
