@Service
@Slf4j
public class WorkerTypeCheckService {

	@Resource
	private CeresRpc ceresRpc;

	/**
	 * 检查手机号是否属于指定工种
	 *
	 * @param mobile 手机号
	 * @param workTypes 要检查的工种枚举数组（可变参数，支持检查多个工种）
	 * @return 如果该手机号的人员包含任一指定工种，返回 true
	 */
	public boolean hasWorkerType(String mobile, WorkTypeEnum... workTypes) {
		if (StringUtils.isBlank(mobile)) {
			return false;
		}

		if (workTypes == null || workTypes.length == 0) {
			return false;
		}

		// 查询个人信息
		List<PersonHighDetailDTO> personInfoList = ceresRpc.queryWorkerByMobile(mobile);

		if (CollectionUtils.isEmpty(personInfoList)) {
			return false;
		}

		List<PersonPositionHighDetailDTO> positions = personInfoList.get(0).getPositions();
		if (CollectionUtils.isEmpty(positions)) {
			return false;
		}

		// 检查是否包含指定工种
		return positions.stream()
			.anyMatch(position -> {
				String workTypeCode = position.getWorkTypeCode();
				return Arrays.stream(workTypes)
					.anyMatch(workTypeEnum -> workTypeEnum.getCode().equals(workTypeCode));
			});
	}

	/**
	 * 校验手机号不能为指定工种，如果匹配则抛出异常
	 *
	 * @param mobile 手机号
	 * @param errorMsg 错误信息
	 * @param workTypes 要检查的工种枚举数组
	 * @throws NrsBusinessException 如果手机号属于指定工种
	 */
	public void checkWorkerType(String mobile, String errorMsg, WorkTypeEnum... workTypes) {
		if (hasWorkerType(mobile, workTypes)) {
			throw new NrsBusinessException(errorMsg);
		}
	}
}

