@Slf4j
@Service
public class DesignFeeCalculator {

	@Resource
	ContractUnifyService contractUnifyService;

	/**
	 * 不使用前端传入的设计费，后端重新计算设计费
	 */
	public void dealDesignFee(ContractReqDTO contractReq) {
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		ContractProjectInfoReq projectInfo = contractReq.getProjectInfo();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();

		Integer needDesignerAmount = Optional.of(contractReq)
				.map(ContractReqDTO::getPromiseInfo)
				.map(PromiseInfoReq::getNeedDesignerAmount)
				.orElse(CommonYesOrNoEnum.NO.getCode());
		if (shouldSkipCalculateDesignFee(projectOrderId, contractType, needDesignerAmount, contractReq.getSignInfo().getSignChannelType())) {
			return;
		}

		Integer houseBuildType = contractReq.getProjectInfo().getHouseBuildType();
		String valuationArea = "";
		if (ContractTypeEnum.DESIGN.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType)) {
			valuationArea = contractReq.getProjectInfo().getValuationArea();
		} else if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
			if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
				return;
			}
			valuationArea = Optional.ofNullable(ContractContextHandler.getPlanAllDTO())
				.map(PlanAllDTO::getPlanInfo)
				.map(PlanInfoDTO::getPricingArea)
				.map(Object::toString)
				.orElse(null);
		}
		DesignSignPriceInfo designSignPriceInfo = contractUnifyService.calculateDesignSignPriceInfo(projectOrderId, contractType, valuationArea, houseBuildType);
		projectInfo.setValuationAreaFromQuote(designSignPriceInfo.getValuationAreaFromQuote().toString());
		projectInfo.setPreDiscountDesignerAmount(designSignPriceInfo.getStandardDesignFeeAmount());
		projectInfo.setDesignerPsLevelName(designSignPriceInfo.getPsLevelName());
	}

