	public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
		createPdfStrategyMap = applicationContext.getBeansOfType(CreateContractPdfBySelfStrategy.class);
	}



	/**
	 * 根据合同类型&业务类型获取对应的策略模式
	 *
	 * @param contractType
	 * @return
	 */
	public CreateContractPdfBySelfStrategy getContractPdfBySelfStrategy(Byte contractType, Byte businessType) {
		CreateContractPdfBySelfStrategy createContractPdfBySelfStrategy = createPdfStrategyMap.get(ContractTypeEnum.getContractPdfBySelfStrategy(contractType, businessType));
		if (createContractPdfBySelfStrategy == null) {
			throw new NrsBusinessException("当前合同不支持自主生成pdf,合同类型为:" + contractType);
		}
		return createContractPdfBySelfStrategy;
	}



