@Service
public class ChangeContractStrategyFactory implements ApplicationContextAware {

	private Map<String, ChangeContractStrategy> changeContractStrategyMap;
	@Override
	public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
		changeContractStrategyMap = applicationContext.getBeansOfType(ChangeContractStrategy.class);
	}

	/**
	 * 根据合同类型获取对应的策略模式
	 * @param contractTypeEnum
	 * @return
	 */
	public ChangeContractStrategy getChangeContractStrategy(ContractTypeEnum contractTypeEnum) {
		if (contractTypeEnum == null) {
			throw new NrsBusinessException("合同策略未配置");
		}

		ChangeContractStrategy changeContractStrategy = changeContractStrategyMap.get(contractTypeEnum.getChangeContractStrategy());

		if (changeContractStrategy == null) {
			throw new NrsBusinessException(contractTypeEnum + " 合同类型不支持");
		}
		return changeContractStrategy;
	}
}

