@Slf4j
@Component
public class MaterialPdfUtil {

	@Resource
	private HtmlRenderUtil htmlRenderUtil;

	@Resource
	private S3Service s3Service;

	@Resource
	private PdfUtils pdfUtils;

	@Resource
	private AtomForPdfRpc atomForPdfRpc;

	@Resource
	private ContractPdfFileHandleService contractPdfFileHandleService;

	// 内网 host
	private static final String TARGE_HOST = "http://file.media.lianjia.com";
	// 外网 host
	private static final String REPLACE_HOST = "https://file.ljcdn.com";

	/**
	 * 生成 PDF 并上传 S3
	 *
	 * @param templateFile 模板文件
	 * @param key          最终上传到 S3 的 key
	 * @param data         数据
	 */
	public String doGeneral(String templateFile, String key, Map<String, Object> data) {

		long startTimeMillis = System.currentTimeMillis();

		String html = htmlRenderUtil.render(templateFile, data);

		String pdfS3Url = pdfUtils.getPdfS3Url(html, null, null);

		String newPdfS3Url = hostReplacement(pdfS3Url);

		LOGGER.info("generalPdf|originalPdfS3Url:{}|newPdfS3Url:{}", pdfS3Url, newPdfS3Url);

		String tempPath = UUID.randomUUID() + ".pdf";
		File file;
		try {
			file = contractPdfFileHandleService.downloadFileFromUrl(newPdfS3Url, tempPath);
			String materialUrl = s3Service.uploadPublic(Files.readAllBytes(file.toPath()), key);
			LOGGER.info("材料清单 PDF 生成成功, url: {}, tempPath: {}, data: {}, cost: {}ms", materialUrl, tempPath, JSON.toJSONString(data), System.currentTimeMillis() - startTimeMillis);
			return materialUrl;
		} catch (IOException e) {
			throw new NrsBusinessException("材料配送清单 PDF 生成失败");
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPath));
		}
	}

	private String hostReplacement(String pdfS3Url) {
		// 判断如果是外网地址开头的 url 替换成内网 host
		if (pdfS3Url.startsWith(REPLACE_HOST)) {
			return pdfS3Url.replace(REPLACE_HOST, TARGE_HOST);
		}
		return pdfS3Url;
	}
}

