	public ContractHandlerInterface getHandler(BaseContractDto baseDto) {
		if (ContractTypeEnum.SUBSCRIBE.getCode().equals(baseDto.getType())) {
			return subscribeContractHandler;
		} else if (ContractTypeEnum.DESIGN.getCode().equals(baseDto.getType())) {
			return designContractHandler;
		} else if (ContractTypeEnum.TERMINAL.getCode().equals(baseDto.getType())) {
			return terminalContractHandler;
		}

		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "不支持的合同类型");
	}

	public BaseContractDto parseDbField(Byte contractType, List<ContractField> fieldList) {
		if (ContractTypeEnum.SUBSCRIBE.getCode().equals(contractType)) {
			return subscribeContractHandler.parseDbField(fieldList);
		} else if (ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
			return designContractHandler.parseDbField(fieldList);
		} else if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
			return terminalContractHandler.parseDbField(fieldList);
		}

		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "不支持的合同类型");
	}
