@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_AUDIT_PASS, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class AuditPassCompanySealListener implements DomainEventHandler<ContractEvent> {
	@Resource
	ContractService contractService;
	@Resource
	ContractBusinessService contractBusinessService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getContractCode())) {
			return;
		}
		LOGGER.info("收到合同事件:{}", payloadData);
		Contract contract = contractService.getByContractCode(payloadData.getContractCode());
		if (Objects.isNull(contract)) {
			LOGGER.error("盖公司章异常，不存在的合同:{}-[签约]", payloadData.getContractCode());
			return;
		}

		if (!ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contract.getStatus())) {
			return;
		}

		//为了事件驱动事务超时,开启新线程去执行
		CompletableFuture.runAsync(()->{
			try {
				contractBusinessService.companySeal(contract);
			} catch (Exception e) {
				//协议平台有可能失败，有定时任务兜底，这里就不报错了
				LOGGER.warn("【签约-审核通过】事件消息触发盖公司章失败，{}", contract.getContractCode(), e);
			}
		});
	}
}

