@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.TERMINAL_CONTRACT_FINISH, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class ContractMergeTerminalFinishListener implements DomainEventHandler<TerminalContractFinishEvent> {

	@Resource
	HomeOrderOperationService homeOrderOperationService;

	@Resource
	ContractService contractService;
	@Resource
	CommonContractService commonContractService;
	@Resource
	ProjectInfoService projectInfoService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Override
	public void handleBiz(TerminalContractFinishEvent payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getContractCode())) {
			return;
		}
		LOGGER.info("合同合并签约解约协议完成监听器,ContractEvent:{}", JSON.toJSONString(payloadData));
		String projectOrderId = payloadData.getProjectOrderId();
		//校验首期款或正签是否签约完成
		List<Byte> contractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.ADVANCE.getCode());
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractTypeList, ContractStatusEnum.SIGNED_STATUS_LIST);
		if(CollectionUtil.isEmpty(contractList)) {
			throw new NrsBusinessException("项目订单首期款或正签未签约完成，不能切换项目类型");
		}
		ProjectInfo projectInfo = projectInfoService.getByProjectOrderIdSwitchOff(projectOrderId);
		//校验项目是否存在
		if (projectInfo == null) {
			throw new NrsBusinessException("项目不存在");
		}
		//校验业务类型
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			throw new NrsBusinessException("非团装项目，此方法不支持切换");
		}
		// ContractMergeTerminalFinish
		CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				homeOrderOperationService.homeOrderTerminal(payloadData.getProjectOrderId());
			} catch (Exception e) {
				LOGGER.error("合同合并签约解约协议完成监听器处理异常,ContractEvent:{}", JSON.toJSONString(payloadData), e);
			}
		}));
	}
}

