@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.CONTRACT_SUBMIT, serverName = "utopia-nrs-sales-project")
@Component
@Slf4j
public class SignCompanySealAfterSubmitListener implements DomainEventHandler<ContractEvent> {
	@Resource
	ContractService contractService;
	@Resource
	ContractBusinessService contractBusinessService;
	@Resource
	SignCompanySealAfterSubmitListener signCompanySealAfterSubmitListenerSelf;
	@Resource
	ContractApolloConfig contractApolloConfig;


	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		Contract contract = contractService.getByContractCode(payloadData.getContractCode());
		if (!ContractStatusEnum.PENDING_COMPANY_SIGN.getCode().equals(contract.getStatus())) {
			return;
		}
		//为了事件驱动事务超时,开启新线程去执行
		CompletableFuture.runAsync(()->{
			try {
				signCompanySealAfterSubmitListenerSelf.companySeal(contract);
			} catch (Exception e) {
				LOGGER.warn("【合同提交后-时间消息】盖公司章重试后依旧失败,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType(), e);
			}
		});
	}

	@Retryable(value = Exception.class, maxAttempts = 3, backoff = @Backoff(value = 30000, multiplier = 1))
	public void companySeal(Contract contract) {
		try {
			LOGGER.info("合同提交后盖公司章开始,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType());
			if (Boolean.TRUE.equals(contractApolloConfig.getSignCompanySealAfterSubmitIsAsync())) {
				contractBusinessService.companySealAsync(contract);
			} else {
				contractBusinessService.companySealSync(contract);
			}
			LOGGER.info("合同提交后盖公司章完成,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType());
		} catch (Exception e) {
			LOGGER.info("合同提交后盖公司章发生异常,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType(), e);
			throw e;
		}
	}


}

