public class CancelPersonalContractListener implements DomainEventHandler<DomainEventDTO<KafkaMessageAthenaDomainEntityEventDTO>> {

	@Resource
	private HomeOrderOperationService homeOrderOperationService;

	@Resource
	private PersonalRelationHandler personalRelationHandler;

	/**
	 * 处理个性化报价单撤回消息
	 * 历史未绑定报价单的合同：字段中包含对应报价单则撤回
	 * 已绑定个性化报价的合同：合同状态回退到草稿中，绑定关系状态置为已取消
	 * @param payloadData
	 * @param eventContextKey
	 */
	@Override
	public void handleBiz(DomainEventDTO<KafkaMessageAthenaDomainEntityEventDTO> payloadData, String eventContextKey) {
		LOGGER.info("开始处理个性化报价单撤回消息, {}", payloadData.getPayloadData());
		KafkaMessageAthenaDomainEntityEventDTO event = payloadData.getPayloadData();
		String projectOrderId = event.getProjectOrderId();
		Integer billType = event.getEntityType();
		// 处理协同报价单 + 团装报价单的撤回
		List<Integer> dealBillTypeList = Arrays.asList(AthenaDomainEntityTypeEnum.SIGN_COOPER_BUDGET_BILL.getCode(), AthenaDomainEntityTypeEnum.GROUP_BUDGET_BILL.getCode());
		if (!dealBillTypeList.contains(billType)) {
			return;
		}

		// 只处理撤回的报价单
		//     预算单状态 * -->> 1:调整中,2:已提交,3:正式版,4:已签约,21:优惠提交,11:已删除
		// 从正式版状态 至 调整中/已提交状态是撤回报价单
		// 预算单状态 3-1 或 3-2 或 2-1 都属于撤回报价单 要作废合同
		if (event.getSourceStatus() == null || event.getEntityStatus() == null) {
			return;
		}

		// 仅处理报价单撤回动作
		if (!isBillCancelAction(event.getSourceStatus(), event.getEntityStatus())) {
			return;
		}

		// 处理附件撤回
		homeOrderOperationService.revokeQuote(event.getBillCode(), NrsOrderKindEnum.QUOTATION_ORDER_NO.getCode(), payloadData.getPayloadData().getProjectOrderId());

		// 撤回协同报价单：处理合同与报价单/S单的绑定关系
		personalRelationHandler.revokeCooperQuotation(projectOrderId, event.getBillCode(), event.getOperatorUcid());
	}

