@EventType(bizType = com.ke.utopia.nrs.salesproject.constant.EventType.QUOTATION_CHANGE_CREATE_ORDER, serverName = DOMAIN_NRS_ORDER_SERVICE)
@Component
@Slf4j
public class ChangeBillToSubOrderListener implements DomainEventHandler<KafkaCommonPayload<KafkaExtDto>> {

	@Resource
	private QuotationRelationCommonService quotationRelationCommonService;
	@Resource
	private ContractServiceImpl contractService;

	/**
	 * 变更单下单完成，将变更单对应 S 单绑定至关联的销售合同
	 */
	@Override
	public void handleBiz(KafkaCommonPayload<KafkaExtDto> payloadData, String eventContextKey) {
		// 主单号
		String homeOrderNo = payloadData.getBody().getExt().getHomeOrderNo();
		// 变更单号
		String changeOrderId = payloadData.getBody().getExt().getProjectChangeNo();
		LOGGER.info("变更单绑定 S 单，开始处理，homeOrderNo={}, changeOrderId={}", homeOrderNo, changeOrderId);

		List<Contract> validPersonalContracts = getValidPersonalContracts(homeOrderNo);
		if (CollectionUtil.isEmpty(validPersonalContracts)) {
			LOGGER.info("订单{}不存在已发起的销售合同", homeOrderNo);
			return;
		}

		for (Contract contract : validPersonalContracts) {
			quotationRelationCommonService.convertChangeToSubOrder(contract, changeOrderId);
		}
		LOGGER.info("变更单绑定 S 单，处理完成，homeOrderNo={}, changeOrderId={}", homeOrderNo, changeOrderId);
	}

	private List<Contract> getValidPersonalContracts(String homeOrderNo) {
		return contractService.getContractList(homeOrderNo).stream()
			.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
			.filter(contract -> ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()))
			.collect(Collectors.toList());
	}
}

