@Component
@Slf4j
public class UserSignTranslatePdfImageListener implements DomainEventHandler<ContractEvent> {
	@Resource
	ContractBusinessService contractBusinessService;

	@Override
	public void handleBiz(ContractEvent payloadData, String eventContextKey) {
		if (Objects.isNull(payloadData.getContractCode())) {
			return;
		}

		//为了事件驱动事务超时,开启新线程去执行
		CompletableFuture.runAsync(()->{
			try {
				contractBusinessService.contractPdfToImageSchedule(payloadData.getContractCode());
			} catch (Exception e) {
				LOGGER.error("事件消息触发PDF转图片失败，{},{}", payloadData.getContractCode(), e);
			}
		});
	}
}

