@EventType(bizType = "freeform-contract-seal-result", serverName = "nrs-sales-project")
@Component
@Slf4j
public class FreeformSealResultListener implements DomainEventHandler<FreeformSealResultEvent> {

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private ContractService contractService;

	@Resource
	private LockService lockService;

	@Resource
	private ContractRedisRepoService contractRedisService;

	@Override
	public void handleBiz(FreeformSealResultEvent event, String eventContextKey) {
		Long instanceId = event.getInstanceId();
		if (Objects.isNull(instanceId)) {
			LOGGER.error("监听协议平台盖章结果消息，实例id为空，消息体：{}", JSON.toJSONString(event));
			return;
		}

		Contract contract = contractService.getContractByInstanceId(instanceId);
		if (Objects.isNull(contract)) {
			LOGGER.error("监听协议平台盖章结果消息，没有查询到相关合同信息，消息体：{}", JSON.toJSONString(event));
			return;
		}

		CompanySealAsyncResultDTO companySealAsyncResultDTO = contractRedisService.getCompanySealResult(contract.getContractCode());
		if (companySealAsyncResultDTO != null) {
			LOGGER.info("异步盖章回调时间间隔，contractCode:{}，时间间隔：{}s", contract.getContractCode(), (System.currentTimeMillis() - companySealAsyncResultDTO.getApplySealTime()) / 1000);
		} else {
			LOGGER.info("异步盖章回调，未找到redis记录信息，contractCode:{}", contract.getContractCode());
		}

		//事件驱动事务超时，开启新的线程去执行
		CompletableFuture.runAsync(()->{
			try {
				lockService.lockElseThrow("contract_company_seal:" + contract.getContractCode(), () -> {
					contractBusinessService.updateCompanySealResult(contract);
					return null;
				}, 10000);
			} catch (Exception e) {
				LOGGER.info("监听协议平台消息，更新盖章结果失败,contractCode:{},contractType:{}", contract.getContractCode(), contract.getType(), e);
			}
		});


	}
}

