		List<SignableOrderInfoGroup> result = new ArrayList<>();
		if (CollectionUtils.isEmpty(signableOrderInfos)) {
			return result;
		}

		// 按公司主体分组
		Map<String, List<SignableOrderInfo>> groupedByCompanyCode = signableOrderInfos.stream()
			.collect(Collectors.groupingBy(SignableOrderInfo::getCompanyCode));

		// 每个公司主体创建一个 group
		groupedByCompanyCode.forEach((companyCode, orderInfoGroup) -> {
			String companyName = orderInfoGroup.get(0).getCompanyName();
			SignableOrderInfoGroup signableOrderInfoGroup = SignableOrderInfoGroup.builder()
				.companyName(companyName)
				.companyCode(companyCode)
				.signableOrderInfos(orderInfoGroup)
				.build();
			result.add(signableOrderInfoGroup);
		});

		return result;
	}
}

