public interface PrivacyOperateStrategy {

    /**
     * 解密隐私信息
     * @param privateDataAccessDTO
     * @return
     */
    String decryptPrivacyInfo(PrivateDataAccessDTO privateDataAccessDTO);

    /**
     * 记录操作
     * @param privateDataAccessDTO
     */
    void recordAndPostProcess(PrivateDataAccessDTO privateDataAccessDTO);

}

@Service
public class PrivacyOperateStrategyFactory implements ApplicationContextAware {

    private Map<String, PrivacyOperateStrategy> privacyOperateStrategyMap;

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
        // 获取所有PrivacyOperateStrategy类型的Bean，并存储在map中
        privacyOperateStrategyMap = applicationContext.getBeansOfType(PrivacyOperateStrategy.class);
    }

    /**
     * 根据PrivacyOperateTypeEnum枚举获取策略
     */
    public PrivacyOperateStrategy getPrivacyOperateStrategy(Integer privacyOperateType) {
        PrivacyOperateTypeEnum privacyOperateTypeEnum = PrivacyOperateTypeEnum.getEnumByType(privacyOperateType);
        if (privacyOperateTypeEnum == null) {
            return null;
        }
        PrivacyOperateStrategy privacyOperateStrategy = privacyOperateStrategyMap.get(privacyOperateTypeEnum.getStrategy());
        if (privacyOperateStrategy == null) {
            return null;
        }
        return privacyOperateStrategy;
    }
}

