public interface AuditCheckStrategy {

    /**
     * 是否支持该合同类型
     *
     * @param dto 合同
     * @return true 支持，false 不支持
     */
    boolean supports(AuditCheckDTO dto);

    /**
     * 判断是否需要专项审核
     */
    boolean auditCheck(AuditCheckDTO dto);

	/**
	 * 路由和校验审核必须的字段是否齐全且合法
	 * 由工厂类调用，返回 true 则直接跳过校验并记录日志
	 */
	boolean isValid(AuditCheckDTO dto);
}

strategy/feeaudit/AuditCheckStrategyFact.source_code_head:
@Slf4j
@Service
public class AuditCheckStrategyFactory {

    @Resource
    private List<AuditCheckStrategy> strategies;

    /**
     * 路由审核校验
	 * 路由不到，就跳过校验；路由到，就执行校验逻辑
     *
     * @param dto 校验参数，由调用方填充；null 表示不在校验范围，直接跳过
     */
    public boolean routeAndValidate(AuditCheckDTO dto) {
        AuditCheckStrategy strategy = route(dto);
        if (strategy == null) {
            LOGGER.info("AuditCheckStrategyFactory 无匹配策略，跳过校验 dto:{}", dto);
            return false;
        }
        return strategy.auditCheck(dto);
    }

	/**
     * 根据合同类型找到对应策略，无匹配则返回 null
     */
    private AuditCheckStrategy route(AuditCheckDTO dto) {
        for (AuditCheckStrategy strategy : strategies) {
			if (Objects.isNull(dto) || !strategy.isValid(dto)){
				return null;
			}
            if (strategy.supports(dto)) {
				LOGGER.info("AuditCheckStrategyFactory 找到匹配策略，校验 dto:{}", dto);
                return strategy;
            }
        }
        return null;
    }
}

strategy/feeaudit/DesignFeeAuditCheckStr.source_code_head:
@Slf4j
@Service
public class DesignFeeAuditCheckStrategy implements AuditCheckStrategy {

	private static final List<Byte> SUPPORTED_TYPES = Arrays.asList(
		ContractTypeEnum.DESIGN.getCode(),
		ContractTypeEnum.DESIGN_CHANGE.getCode()
	);

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private AtomBudgetRpc atomBudgetRpc;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ContractUnifyService contractUnifyService;

	@Override
	public boolean supports(AuditCheckDTO dto) {
		// 仅当开关开启+(设计or设计变更)+整装+非合并合同+2.5流程时，才走设计费审核
		return contractApolloConfig.getDesignFeeCheckEnabled()
			&& SUPPORTED_TYPES.contains(dto.getContractType())
			&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(dto.getBusinessType())
			&& !dto.isMergeDesignContract()
			&& commonBusinessService.isPROCESS_V2_5(dto.getProjectOrderId(), dto.getContractType());
	}

	@Override
	public boolean auditCheck(AuditCheckDTO dto) {
		DesignFeeCheckVO.CheckResponse response = atomBudgetRpc.checkDesignFeeChangeAmount(dto.getProjectOrderId(),
			dto.getPreDiscountDesignerAmount(), dto.getAfterDiscountDesignerAmount());
		return response.getIsExceedBottom();
	}

	@Override
	public boolean isValid(AuditCheckDTO dto) {
		return StringUtils.isNotBlank(dto.getProjectOrderId())
			&& Objects.nonNull(dto.getContractType())
			&& Objects.nonNull(dto.getBusinessType())
			&& Objects.nonNull(dto.getPreDiscountDesignerAmount())
			&& Objects.nonNull(dto.getAfterDiscountDesignerAmount());
	}
}

