public interface FieldHandleStrategy {

    default ContractFieldQueryResp handleField(String key, String value) {
        return ContractFieldQueryResp.builder()
                .fieldKey(key)
                .fieldValue(value)
                .build();
    }

}

@Service
public class FieldHandleStrategyFactory implements ApplicationContextAware {

	private Map<String, FieldHandleStrategy> fieldHandleStrategyMap;

	@Override
	public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
		fieldHandleStrategyMap = applicationContext.getBeansOfType(FieldHandleStrategy.class);
	}

	/**
	 * 根据ContractFieldQueryEnum枚举获取策略
	 */
	public FieldHandleStrategy getFieldHandleStrategy(ContractFieldQueryEnum contractFieldQueryEnum) {
		FieldHandleStrategy fieldHandleStrategy = fieldHandleStrategyMap.get(contractFieldQueryEnum.getFieldStrategy());
		if (fieldHandleStrategy == null) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), String.format("对应字段:【%s】不支持查询", contractFieldQueryEnum.getFieldKey()), Level.WARN);
		}
		return fieldHandleStrategy;
	}

}

strategy/fieldstrategy/TotalDurationHand.source_code_head:
@Component
public class TotalDurationHandleStrategy implements FieldHandleStrategy {

    @Override
    public ContractFieldQueryResp handleField(String key, String value) {
        ContractFieldQueryResp contractFieldQueryResp = ContractFieldQueryResp.builder()
                .fieldKey(key)
                .build();
        if (value == null || value.isEmpty() || value.equals("/") || Integer.parseInt(value) == 0 || Integer.valueOf(value).compareTo(150) > 0 || Integer.valueOf(value).compareTo(50) < 0) {
            contractFieldQueryResp.setFieldValue("/");
        } else {
            contractFieldQueryResp.setFieldValue(value);
        }
        return contractFieldQueryResp;
    }
}
